Definition art_lcd_fp (sp ca spb ris c nf : Z) : list (Z * Z) :=
  [ (sp - 320, 320); (ca + 80 * c, 4); (ca + 80 * c + 16, 64); (ca + 2576, 8); (ris + 128 * c, 128); (spb + c * 2 ^ 32 + 3758096384 + 4 * nf, 32) ].

